item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic x,
    output logic z
);
    // Power-up initialization implements the specified initial reset to zero.
    logic xor_r = 1'b0;
    logic and_r = 1'b0;
    logic or_r  = 1'b0;

    always_ff @(posedge clk) begin
        xor_r <= x "'^ xor_r;
        and_r <= x & ~and_r;
        or_r  <= x | ~or_r;
    end

    assign z = ~(xor_r | and_r | or_r);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 1'"'b0;
    wire [255:0] z;
    logic [255:0] x;
    logic [2:0] expected [0:255];
    integer sequence_id;
    integer step;
    integer checks = 0;

    for (genvar g = 0; g < 256; g = g + 1) begin : instances
        TopModule dut (.clk(clk), .x(x[g]), .z(z[g]));
    end

    function automatic logic [2:0] transition(input logic [2:0] state, input logic bit_x);
        case ({state, bit_x})
            4'b0000: transition = 3'b001;
            4'b0001: transition = 3'b111;
            4'b0010: transition = 3'b000;
            4'b0011: transition = 3'b111;
            4'b0100: transition = 3'b011;
            4'b0101: transition = 3'b101;
            4'b0110: transition = 3'b010;
            4'b0111: transition = 3'b101;
            4'b1000: transition = 3'b101;
            4'b1001: transition = 3'b011;
            4'b1010: transition = 3'b100;
            4'b1011: transition = 3'b011;
            4'b1100: transition = 3'b111;
            4'b1101: transition = 3'b001;
            4'b1110: transition = 3'b110;
            4'b1111: transition = 3'b001;
            default: transition = 3'bxxx;
        endcase
    endfunction

    task automatic check_outputs;
        for (integer i = 0; i < 256; i = i + 1) begin
            if (z[i] "'!== (expected[i] == 3'"'b000))
                "'$fatal(1, "FAIL sequence=%0d step=%0d state=%b z=%b", i, step, expected[i], z[i]);
            checks = checks + 1;
        end
    endtask

    initial begin
        x = '"'0;
        for (sequence_id = 0; sequence_id < 256; sequence_id = sequence_id + 1)
            expected[sequence_id] = 3'b000;
        #1;
        check_outputs();
        for (step = 0; step < 8; step = step + 1) begin
            for (sequence_id = 0; sequence_id < 256; sequence_id = sequence_id + 1)
                x[sequence_id] = (sequence_id >> step) & 1;
            #1;
            check_outputs();
            for (sequence_id = 0; sequence_id < 256; sequence_id = sequence_id + 1)
                expected[sequence_id] = transition(expected[sequence_id], x[sequence_id]);
            clk = 1'b1;
            #1;
            check_outputs();
            clk = 1'b0;
            #1;
            check_outputs();
        end
        "'$display("PASS: 256 input sequences of length 8; %0d output checks", checks);
        $finish;
    end

    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_status=$?
    cat dev_simulation.log
else
    simulation_status=not_run
fi
python3 - "$compile_status" "$simulation_status" <<'"'PY'
import json, sys
from pathlib import Path
c, s = sys.argv[1:]
report = {
    'revision_count': 0,
    'contract_corrections': [],
    'checks': [
        {'name': 'contract_gate', 'result': 'passed_structure_only', 'log': 'contract_validation.log'},
        {'name': 'static_review', 'result': 'passed', 'details': 'Exact ports, initialized one-bit state, simultaneous nonblocking rising-edge updates, combinational NOR; no additional reset or latency.'},
        {'name': 'iverilog_compile', 'exit_code': int(c), 'log': 'dev_compile.log', 'command': 'timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv'},
        {'name': 'development_simulation', 'exit_code': int(s) if s "'!= '"'not_run' else None, 'log': 'dev_simulation.log', 'command': 'timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim', 'coverage': '256 independently initialized DUTs cover all binary input sequences of length eight, initial output, positive-edge transitions, input-only changes and falling-edge output stability.'}
    ],
    'development_outcome': 'passed' if c == '0' and s == '0' else 'tool_or_test_failure',
    'limitations': ['Development tests only; official evaluation results are unavailable.', 'No synthesis, timing analysis or board validation performed.', 'Power-up register initialization expresses the specified initial zero state; no runtime reset exists.', 'Binary input sequences tested; unspecified X/Z input behavior is not an acceptance criterion.']
}
Path('worker_report.json').write_text(json.dumps(report, indent=2) + '\\n')
PY"

